/* Table of diagnostic codes for the Events page: code, name, meaning and a collapsed "how to fix".
   Row: [code, group, name EN, name RU, meaning EN, meaning RU, fix EN, fix RU]. Codes and technical terms stay English. */
var ERROR_GROUPS=[['monitor',['Monitoring checks','Проверки мониторинга']],['switch',['Switching and Auto','Переключение и Auto']],['service',['Monitor service and page','Служба мониторинга и страница']],['helper',['LAN helper','LAN-помощник']],['telegram',['Telegram','Telegram']],['setup',['Settings and wizards','Настройки и мастера']],['speed',['Speed tests and scans','Тесты скорости и сканирование']],['data',['Data, clock and history','Данные, часы и история']]];
var ERROR_ROWS=[
 ["CLIENT-CONTROL-PATH-MISMATCH", "helper", "Management route uses another interface", "Управление идёт через другой интерфейс", "The OS management route differs from the selected client witness, for example when two routers share the same private subnet.", "Путь управления ОС отличается от выбранного интерфейса проверки, например при одинаковой подсети двух роутеров.", "The helper refuses before credentials/session are sent. Establish the target identity and an unambiguous management path; do not change host networking automatically.", "Помощник отказывает до отправки пароля/сессии. Подтвердите идентичность и однозначный путь управления; не меняйте сеть компьютера автоматически."],
 ["WAN-001", "monitor", "Internet is down at the router", "Нет интернета на роутере", "The router itself cannot reach the internet, not only the VPN.", "Сам роутер не достаёт до интернета, а не только VPN.", "Inspect independent WAN, DNS and VPN evidence before blaming the provider. A modem restart is a separate deliberate action, not an automatic application fix.", "Сначала различите WAN, DNS и VPN по независимым данным. Перезапуск модема — отдельное осознанное действие, а не автоматическое исправление приложения."],
 ["DNS-001", "monitor", "DNS check did not pass", "DNS-проверка не прошла", "The control DNS query through this VPN did not produce a validated answer. Other DNS paths, cached names or direct HTTPS may still work; the code alone does not identify the cause.", "Контрольный DNS-запрос через этот VPN не дал подтверждённого ответа. Другой DNS, кэшированные имена или прямые HTTPS-запросы могут работать; сам код не устанавливает причину.", "Repeat the check and inspect the saved DNS/HTTPS results, resolver reachability, routing and filtering. Coordinate any profile restart with managed Auto Stop/recovery.", "Повторите проверку и изучите сохранённые результаты DNS/HTTPS, доступность DNS-сервера, маршрутизацию и фильтрацию. Перезапуск профиля согласуйте со штатным Stop/восстановлением Auto."],
 ["VPN-001", "monitor", "VPN did not connect", "VPN не подключился", "The VPN connection could not be established. The cause may stay unknown.", "Не удалось установить соединение VPN. Причина может остаться неизвестной.", "Inspect the exact tunnel/credential/endpoint failure. Before editing or reconnecting stock profiles, complete managed Stop/recovery; do not restart a working client just to change its status.", "Изучите точный отказ туннеля/доступа/сервера. До правки или переподключения штатного профиля завершите управляемый Stop/восстановление; не перезапускайте рабочий клиент ради статуса."],
 ['VPN-002','monitor','VPN login rejected','VPN отклонил вход','The VPN server rejected the login or the key.','VPN-сервер отклонил логин или ключ.','Open the profile in GL.iNet and re-enter the login and password or import the config again. Check that the subscription is active.','Откройте профиль в GL.iNet и заново введите логин и пароль или импортируйте конфиг. Проверьте, что подписка активна.'],
 ['VPN-003','monitor','HTTPS availability below threshold','Недостаточно успешных HTTPS-проверок','Fewer than two of three HTTPS checks succeeded through the connected VPN. Some traffic may still pass. This code alone does not establish complete loss of Internet access.','Через подключённый VPN успешно прошли менее двух из трёх HTTPS-проверок. Часть трафика может проходить. Сам код не доказывает полное отсутствие доступа в Интернет.','Read the saved HTTPS success count, DNS result and endpoint details. Retry the check; investigate repeated failures before reconnecting a working VPN.','Посмотрите сохранённое число успешных HTTPS-проверок, результат DNS и сведения об адресах проверки. Повторите проверку; перед переподключением работающего VPN выясните причину повторяющихся сбоев.'],
 ["VPN-MTU", "monitor", "Large packets are lost", "Большие пакеты теряются", "Small checks (HTTPS, DNS, a small ping) pass through this VPN, but no large echo of tunnel size came back from either check address: a path MTU black hole. Pages may open while uploads, video calls and other large transfers hang. The large-packet check runs every 5 minutes and on every check while the hole is seen; Auto counts each such check as a failure and prefers the other tunnel when it passes the check.", "Малые проверки (HTTPS, DNS, малый ping) через этот VPN проходят, но ни один большой эхо-пакет размером с туннель не вернулся ни от одного адреса проверки: «чёрная дыра» MTU. Страницы могут открываться, а загрузки, видеозвонки и другие большие передачи зависают. Проверка больших пакетов идёт раз в 5 минут и на каждой проверке, пока дыра видна; Auto считает каждую такую проверку сбоем и предпочитает другой туннель, если он её проходит.", "Lower the MTU of this VPN profile in GL.iNet (for WireGuard try 1280-1380) or try another server of the provider. If both tunnels show it, check the uplink (PPPoE, mobile or a modem with a small MTU). The router itself already clamps TCP MSS on the tunnels (GL firewall zones, mtu_fix).", "Уменьшите MTU этого VPN-профиля в GL.iNet (для WireGuard попробуйте 1280-1380) или выберите другой сервер провайдера. Если это видно на обоих туннелях, проверьте подключение к интернету (PPPoE, мобильная связь или модем с малым MTU). TCP MSS на туннелях роутер уже ограничивает сам (зоны брандмауэра GL, mtu_fix)."],
 ['VPN-004','monitor','VPN server name does not resolve','Имя VPN-сервера не находится','The name of the VPN server cannot be resolved to an address.','Имя VPN-сервера не удаётся превратить в адрес.','Check DNS on the router and the server name in the profile. Use the server IP address if the provider gives one.','Проверьте DNS на роутере и имя сервера в профиле. Если провайдер даёт IP-адрес сервера, используйте его.'],
 ['TLS-001','monitor','Certificate check failed','Ошибка проверки сертификата','The HTTPS certificate was not accepted. The program never turns the check off by itself.','Сертификат HTTPS не принят. Программа никогда не отключает проверку сама.','Check the router date and time (a wrong clock breaks certificates) and that the package ca-bundle is installed.','Проверьте дату и время на роутере (неверные часы ломают сертификаты) и что установлен пакет ca-bundle.'],
 ['ROUTE-001','monitor','Traffic goes another way','Трафик идёт другим путём','The real route differs from the selected one.','Реальный маршрут отличается от выбранного.','Open GL.iNet → VPN Dashboard and check the order of the VPN rules. Do not change rules while Auto is working.','Откройте GL.iNet → VPN Dashboard и проверьте порядок правил VPN. Не меняйте правила, пока работает Auto.'],
 ['CHECK-001','monitor','Check not confirmed','Проверка не подтверждена','There is not enough evidence yet; the state stays “unknown”. It is shown while a VPN is still being checked.','Пока недостаточно данных; состояние остаётся «неизвестно». Показывается, пока VPN ещё проверяется.','Wait one or two check intervals. If it stays, press “Check now” on Home (Console: Channels tab).','Подождите один-два интервала проверки. Если не проходит, нажмите «Проверить сейчас» на «Главной» (в «Пульте» — вкладка «Каналы»).'],
 ['SWITCH-001','switch','No ready reserve','Нет готового резерва','There is no reserve VPN that passed its checks, so there is nowhere to switch.','Нет резервного VPN, прошедшего проверки, поэтому переключаться некуда.','Connect another VPN profile in GL.iNet and select it as the reserve in Settings → Channels: primary and reserve (Console: Channels → Change the channel pair).','Подключите ещё один VPN-профиль в GL.iNet и выберите его резервным в «Настройки → Каналы: основной и резерв» (в «Пульте» — «Каналы» → «Изменить пару каналов»).'],
['AUTO-CONTROL-UNVERIFIED','switch','Auto request not confirmed','Запрос Auto не подтверждён','The router answered, but not with a clear “accepted”. Nothing is assumed.','Роутер ответил, но не ясным «принято». Ничего не предполагается.','Look at the Auto switch and the status line next to it; press it again only if nothing changed after a minute.','Посмотрите на переключатель Auto и строку состояния рядом с ним; нажмите снова, только если за минуту ничего не изменилось.'],
 ['AUTO-CONTROL-FAILED','switch','Auto request got no answer','Запрос Auto остался без ответа','The router did not answer the Start or Stop request. The page re-read the router state: had the command taken effect it would say “done”; it is never sent again by itself.','Роутер не ответил на запрос «Включить» или «Выключить». Страница перечитала состояние роутера: если бы команда сработала, она сказала бы «готово»; сама она команду не повторяет.','Press Retry when the router answers again. Reload the page and check the Monitoring service lamp (Settings → System and diagnostics; Console: System tab). If the router is unreachable, use the emergency return in Help (topic “I have no internet”).','Обновите страницу и проверьте лампу «Службы мониторинга» (Настройки → Система и диагностика; в «Пульте» — вкладка «Система»). Если роутер недоступен, используйте аварийный возврат из «Помощи» (тема «У меня пропал интернет»).'],
 ["AUTO-START-REFUSED", "switch", "Auto start refused", "Запуск Auto отклонён", "The router refused to start Auto; the reasons are listed with their codes.", "Роутер отказался запускать Auto; причины перечислены с кодами.", "Read the current mode-specific blockers. Prepared continuous mode uses its own router evidence; only a client-confirmed trial requires its matching LAN certificate. Repeated clicks do not repair prerequisites.", "Прочитайте текущие причины своего режима. Подготовленный непрерывный режим использует собственные данные роутера; соответствующий LAN-сертификат нужен клиентскому тесту. Повторные нажатия не исправляют условия."],
 ['ROLLBACK-GIVEN-UP','switch','Automatic return stopped','Автоматический возврат остановлен','The return to the primary failed twice. The program stopped trying, keeps only VPN traffic allowed and turned Auto off.','Возврат на основной не удался дважды. Программа перестала пытаться, пропускает только трафик через VPN и выключила Auto.','Check the VPN rule order in the router (Help → “I have no internet” (emergency return)), restore it by hand, then close the journal with the emergency command.','Проверьте порядок VPN-правил на роутере («Помощь» → «У меня пропал интернет» (аварийный возврат)), восстановите его вручную и закройте журнал аварийной командой.'],
  ['EXIT-TRACE-FAILED','switch','Exit address could not be read','Не удалось прочитать внешний адрес','The check of the address the internet sees through the VPN got no clear answer (cut, garbled or not IPv4). Nothing is switched on such an answer.','Проверка адреса, который видит интернет через VPN, не получила ясного ответа (оборван, искажён или не IPv4). По такому ответу ничего не переключается.','Usually temporary. If it repeats, check the VPN server and that IPv4 works through it.','Обычно временно. Если повторяется, проверьте VPN-сервер и что через него работает IPv4.'],
 ['STOP-UNCONFIRMED','switch','Stop not confirmed','Остановка не подтверждена','The Stop request could not be saved on the router. A running failure test was still cleaned up.','Запрос остановки не удалось сохранить на роутере. Запущенный тест сбоя всё равно убран.','Turn Auto off with the Auto switch again. If it repeats, use the emergency return in Help (topic “I have no internet”), or stop the service in LuCI → System → Startup.','Ещё раз выключите Auto переключателем. Если повторяется, используйте аварийный возврат из «Помощи» (тема «У меня пропал интернет») или остановите службу в LuCI → «Система» → «Автозапуск».'],
 ["SWITCH-002", "switch", "Internet not restored after the switch", "Интернет не вернулся после переключения", "The switch was applied but the following checks failed.", "Переключение выполнено, но последующие проверки не прошли.", "Inspect the recovery result and both paths. A requested rollback is not confirmed restoration; do not start another test until the current state is understood.", "Проверьте итог восстановления и оба пути. Запрошенный откат не является подтверждённым возвратом; не начинайте другой тест до выяснения текущего состояния."],
 ['SWITCH-003','switch','Switch could not be applied','Переключение не удалось применить','The route change itself failed (not the same as SWITCH-002).','Сама смена маршрута не удалась (это не то же самое, что SWITCH-002).','Open Help → “The router stays on the reserve VPN” and check the VPN rule order in GL.iNet.','Откройте «Помощь» → «Роутер остаётся на резервном VPN» и проверьте порядок правил VPN в GL.iNet.'],
 ["CONFIG-001", "switch", "Automation paused after manual change", "Автоматика на паузе после ручного изменения", "Someone changed the VPN settings by hand, so automation stepped aside.", "Кто-то изменил настройки VPN вручную, поэтому автоматика отошла в сторону.", "Inspect the external edit and actual cleanup result. Revalidate identities/policy for the selected mode; do not impose a LAN trial on prepared router-probed mode or compete with the operator edit.", "Изучите внешнюю правку и фактическую очистку. Перепроверьте идентичность/политику своего режима; не навязывайте LAN-тест подготовленному router-probed режиму и не конкурируйте с правкой оператора."],
 ['SYSTEM-001','service','Unsupported firmware or missing tool','Неподдерживаемая прошивка или нет программы','The firmware version or a required tool is not supported.','Версия прошивки или нужная программа не поддерживается.','Compare with the tested firmware (GL.iNet 4.11.0) in Router readiness (Settings → System and diagnostics; Console: System tab). Monitoring still works; Auto needs the supported firmware.','Сравните с проверенной прошивкой (GL.iNet 4.11.0) в «Готовности роутера» (Настройки → Система и диагностика; в «Пульте» — вкладка «Система»). Мониторинг работает, а для Auto нужна поддерживаемая прошивка.'],
 ['MONITOR-START-REQUESTED','service','Start requested','Запуск запрошен','The monitor was switched on. This is not yet proof that it runs.','Мониторинг включён. Это ещё не доказательство, что он работает.','Wait up to a minute for fresh data; the traffic light turns green.','Подождите до минуты свежих данных; светофор станет зелёным.'],
 ['MONITOR-ALWAYS-ON','service','Monitoring always runs','Мониторинг работает всегда',"Monitoring always runs and cannot be turned off. A stop request is refused, with Auto on or off; Stop Auto never stops monitoring.","Мониторинг работает всегда и не выключается. Запрос на остановку отклонён, независимо от того, включён Auto или нет; остановка Auto мониторинг не останавливает.","Nothing to do: monitoring keeps running. If the page says monitoring is not running, that is an error: press Restore monitoring; if it does not come back, reinstall the package.","Делать ничего не нужно: мониторинг продолжает работать. Если страница пишет, что мониторинг не работает, это ошибка: нажмите «Восстановить мониторинг»; если он не вернулся, переустановите пакет."],
 ['MONITOR-JOURNAL-UNVERIFIED','service','Journal cannot be read','Журнал не читается','The transaction journal is damaged or unreadable.','Журнал транзакций повреждён или не читается.','Do not delete it. Follow Help → “I have no internet” and router-test-kit/EMERGENCY.md.','Не удаляйте его. Следуйте «Помощи» → «У меня пропал интернет» и router-test-kit/EMERGENCY.md.'],
 ['MONITOR-SAVE-FAILED','service','Setting not saved','Настройка не сохранилась','The router did not confirm the saved setting.','Роутер не подтвердил сохранение настройки.','Try again. If it repeats, check free space (df -h /etc) and the system log (logread).','Повторите. Если снова, проверьте свободное место (df -h /etc) и системный журнал (logread).'],
 ['MONITOR-SERVICE-UNCONFIRMED','service','Service change not confirmed','Смена состояния службы не подтверждена','The setting may be saved but the service did not confirm the start or stop.','Настройка могла сохраниться, но служба не подтвердила запуск или остановку.','After a minute check Monitoring service (Settings → System and diagnostics; Console: System tab); if its lamp is not green, press “Restore monitoring” there.','Через минуту посмотрите «Службу мониторинга» (Настройки → Система и диагностика; в «Пульте» — вкладка «Система»); если лампа не зелёная, нажмите там «Восстановить мониторинг».'],
 ['MONITOR-INVALID','service','Invalid request','Неверный запрос','The request had wrong fields. Nothing was written.','В запросе неверные поля. Ничего не записано.','Reload the page (Ctrl+F5). If it repeats, the page and the program versions differ: see the notice at the top of the page.','Обновите страницу (Ctrl+F5). Если повторяется, версии страницы и программы различаются: см. сообщение вверху страницы.'],
 ['MONITOR-RPC-UNCONFIRMED','service','No confirmed answer','Нет подтверждённого ответа','The browser did not get a confirmed answer from the router.','Браузер не получил подтверждённого ответа от роутера.','Reload the status. Do not assume the monitor stopped.','Обновите статус. Не считайте, что мониторинг остановился.'],
 ['RPC-UNAVAILABLE','service','Router does not answer','Роутер не отвечает','The page cannot get the status from the router; old values are shown.','Страница не получает статус от роутера; показаны старые значения.','Reload the page and sign in to LuCI again. Then Help → “The page is old, empty or says the monitor is not running”.','Обновите страницу и войдите в LuCI снова. Затем «Помощь» → «Страница старая, пустая или пишет, что мониторинг не работает».'],
 ['PRIMARY-PROVEN','switch','The primary is already proven','Основной уже проверен','After a restart the primary channel was already proven healthy, so Auto returns to it directly instead of continuing on the reserve.','После перезапуска основной канал уже проверен, поэтому Auto сразу возвращается на него, а не продолжает на резерве.','Nothing to do; Auto continues by the usual rules.','Ничего делать не нужно; Auto продолжает по обычным правилам.'],
 ['SESSION-ORDER','switch','Saved channel order differs','Сохранённый порядок каналов другой','After a restart the saved channel order of the Auto session did not match, so Auto uses the usual recovery.','После перезапуска сохранённый порядок каналов сессии Auto не совпал, поэтому Auto идёт обычным восстановлением.','Nothing to do; Auto continues by the usual rules.','Ничего делать не нужно; Auto продолжает по обычным правилам.'],
 ['RESUME-MARKER-UNREADABLE','switch','Resume marker unreadable','Метка возобновления не читается','The marker that Auto was on before the restart could not be read, so the fast start on the reserve is not used.','Метку о том, что Auto был включён до перезапуска, прочитать не удалось, поэтому быстрый старт на резерве не используется.','Nothing to do; Auto continues by the usual rules.','Ничего делать не нужно; Auto продолжает по обычным правилам.'],
 ['BOOT-RESERVE-ADOPTED','switch','Auto resumed on the reserve after a restart','Auto возобновлён на резерве после перезапуска','The router restarted while the reserve carried traffic. Auto checked the route and the reserve again and continued on the reserve; it returns to the primary by the usual rules.','Роутер перезапускался, когда трафик шёл через резерв. Auto заново проверил маршрут и резерв и продолжил на резерве; на основной вернётся по обычным правилам.','Nothing to do.','Ничего делать не нужно.'],
 ['BOOT-RESERVE-UNVERIFIED','switch','Reserve not confirmed after a restart','Резерв не подтверждён после перезапуска','After a restart the reserve route or its health could not be confirmed, so Auto uses the usual recovery and waits for the primary.','После перезапуска не удалось подтвердить маршрут или работу резерва, поэтому Auto идёт обычным восстановлением и ждёт основной канал.','Nothing to do; Auto turns on by itself.','Ничего делать не нужно; Auto включится сам.'],
 ['DNS-MARK-UNVERIFIED','switch','LAN DNS channel not confirmed','DNS-канал LAN не подтверждён','After a switch or during Auto the program writes the mark of the active channel into every GL dns_mark rule (/proc/dns_mark/rule*/mark), so LAN DNS goes through the same tunnel as the traffic. A write or its read-back did not confirm it. The traffic switch itself stays valid and is not rolled back; LAN DNS may still go through the previous tunnel.','После переключения или в работе Auto программа записывает метку активного канала во все правила GL dns_mark (/proc/dns_mark/rule*/mark), чтобы DNS клиентов LAN шёл через тот же туннель, что и трафик. Запись или её проверка чтением не подтвердились. Само переключение трафика остаётся верным и не откатывается; DNS клиентов LAN может идти через прежний туннель.','Look at the system log line DNS-MARK-SYNC and at cat /proc/dns_mark/dump. Auto repeats the write on its next verified pass; a GL VPN restart (fw3 / vpn-client reload) rebuilds the rules.','Посмотрите строку DNS-MARK-SYNC в системном журнале и вывод cat /proc/dns_mark/dump. Auto повторит запись на следующем подтверждённом проходе; перезапуск VPN в GL (fw3 / vpn-client reload) пересоздаёт правила.'],
 ['DNS-MARK-UNAVAILABLE','switch','No GL dns_mark module','Нет модуля GL dns_mark','This firmware has no /proc/dns_mark, so there is no per-tunnel LAN DNS marking to follow. Nothing is written; LAN DNS follows the rules of the firmware itself.','В этой прошивке нет /proc/dns_mark, поэтому нет пометки DNS клиентов LAN по туннелям. Ничего не записывается; DNS клиентов LAN идёт по правилам самой прошивки.','Nothing to do on firmware without the module. On GL 4.11 the module is expected: compare with lsmod and the firmware version.','На прошивке без модуля ничего делать не нужно. На GL 4.11 модуль ожидается: сверьте lsmod и версию прошивки.'],
 /* LAN DNS through both tunnels (03.11.2026, dns_dual.py / lua/dns_dual.lua): owner option dns_dual, default off. */
 ['DNS-DUAL-UNVERIFIED','switch','DNS through both tunnels not confirmed','DNS через оба туннеля не подтверждён','With option dns_dual on, Auto gives the dnsmasq of each tunnel (GL per-tunnel instance) the DNS servers of the other tunnel as well, so a LAN lookup is answered through whichever tunnel replies first. Writing that small file (/tmp/dnsmasq.d.<tunnel>/homensai-dns-dual.conf), the dnsmasq --test check, the restart of that dnsmasq or its running state was not confirmed. The previous file was put back (none: the GL configuration), so LAN DNS keeps working as before through the active tunnel only; the same file is not tried again until Auto restarts. Traffic and its route are not affected; no DNS goes to the WAN.','При включённой опции dns_dual Auto даёт dnsmasq каждого туннеля (отдельный экземпляр GL на туннель) ещё и DNS-серверы другого туннеля, чтобы запрос клиента LAN получил ответ через тот туннель, который ответит первым. Запись этого небольшого файла (/tmp/dnsmasq.d.<туннель>/homensai-dns-dual.conf), проверка dnsmasq --test, перезапуск этого dnsmasq или его рабочее состояние не подтвердились. Прежний файл возвращён (если его не было — конфигурация GL), поэтому DNS клиентов LAN работает как раньше, только через активный туннель; тот же файл не пробуется снова до перезапуска Auto. Трафик и его маршрут не затронуты; DNS не уходит в WAN.','Look at logread -e DNS-DUAL-SYNC and at logread -e dnsmasq (for example failed to bind server socket). Check that /var/etc/dnsmasq.conf.<tunnel> exists and ubus call service list shows the instance running. To switch the feature off: uci set homensai_vpn.main.dns_dual=0; uci commit homensai_vpn.','Посмотрите logread -e DNS-DUAL-SYNC и logread -e dnsmasq (например failed to bind server socket). Проверьте, что /var/etc/dnsmasq.conf.<туннель> существует и ubus call service list показывает экземпляр запущенным. Выключить функцию: uci set homensai_vpn.main.dns_dual=0; uci commit homensai_vpn.'],
 ['DNS-DUAL-UNAVAILABLE','switch','DNS through both tunnels not possible here','DNS через оба туннеля здесь невозможен','Option dns_dual is on, but fewer than two per-tunnel GL dnsmasq instances of the Auto pair were found (/var/etc/dnsmasq.conf.<tunnel> with conf-dir /tmp/dnsmasq.d.<tunnel> and its mark). Nothing is changed: LAN DNS goes through the active tunnel as GL configures it.','Опция dns_dual включена, но найдено меньше двух экземпляров dnsmasq GL для туннелей пары Auto (/var/etc/dnsmasq.conf.<туннель> с conf-dir /tmp/dnsmasq.d.<туннель> и его меткой). Ничего не меняется: DNS клиентов LAN идёт через активный туннель так, как его настроил GL.','Expected on firmware other than GL 4.x with VPN instances, or while a tunnel instance is not running yet. On GL 4.11 compare ls /tmp/dnsmasq.d.* and /var/etc/dnsmasq.conf.*; Auto checks again on every pass.','Ожидаемо на прошивке, отличной от GL 4.x с экземплярами VPN, или пока экземпляр туннеля ещё не запущен. На GL 4.11 сравните ls /tmp/dnsmasq.d.* и /var/etc/dnsmasq.conf.*; Auto проверяет снова на каждом проходе.'],
 /* Best server inside a channel (2.1.0, server_pick.lua/.py): measured from the router, off until the owner switches it on. */
 ['SERVER-PICKED','switch','Channel server changed','Сервер канала сменён','The reserve channel was down and carried no traffic, so Auto itself put the fastest live server of its GL server list into it (uci and ifdown/ifup of that interface only), inside its own lock: the working channel is not touched and Auto is not restarted. The new server passed the usual channel check (DNS and HTTPS through the tunnel). The log line names both servers and their ping.','Резервный канал не работал и не вёз трафик, поэтому сам Auto поставил в него самый быстрый живой сервер из списка серверов GL этого канала (uci и ifdown/ifup только этого интерфейса), внутри своей блокировки: работающий канал не трогается, Auto не перезапускается. Новый сервер прошёл обычную проверку канала (DNS и HTTPS через туннель). В строке журнала названы оба сервера и их пинг.','Nothing to do. To stop it, switch off "Pick the best server" in Settings → Channels: primary and reserve (Console: Servers tab).','Ничего делать не нужно. Чтобы отключить, снимите «Подбирать лучший сервер» в «Настройки → Каналы: основной и резерв» (в «Пульте» — вкладка «Серверы»).'],
 ['SERVER-PICK-FAILED','switch','Channel server not changed','Сервер канала не сменён','A command of the server change (uci or ifdown/ifup) did not succeed, or the new server did not pass the channel check (DNS and HTTPS through the tunnel) within 60 s. Auto put the previous server back the same way; the log line says "rolled back" (or "rollback failed").','Команда смены сервера (uci или ifdown/ifup) не выполнилась или новый сервер не прошёл проверку канала (DNS и HTTPS через туннель) за 60 с. Auto тем же способом вернул прежний сервер; в строке журнала написано «rolled back» (или «rollback failed», если вернуть не удалось).','Open VPN > VPN Client in GL.iNet and check this channel. Save the system log (logread | grep homensai) if it repeats.','Откройте VPN > VPN Client в GL.iNet и проверьте этот канал. Если повторяется, сохраните системный журнал (logread | grep homensai).'],
 ['SERVER-PICK-WAITING-VENDOR','switch','GL is switching the server itself','GL сам меняет сервер','The GL firmware is switching the server of this channel itself (its tunnel-switch lock is held). The program does not interfere and looks again later.','Прошивка GL сама меняет сервер этого канала (занята её блокировка tunnel-switch). Программа не вмешивается и посмотрит позже.','Nothing to do.','Ничего делать не нужно.'],
 ['SERVER-PICK-LIMIT','switch','Server change limit reached','Достигнут предел смены серверов','The server of this channel was changed 4 times within the last hour. Further changes wait, so a channel with a problem on every server is not switched around in a loop.','Сервер этого канала уже меняли 4 раза за последний час. Следующие смены ждут, чтобы канал с проблемой на всех серверах не перебирался по кругу.','Check the channel in GL.iNet: if every server fails, the cause is likely the account or the provider.','Проверьте канал в GL.iNet: если не работает ни один сервер, причина, скорее всего, в подписке или у провайдера.'],
 ['SERVER-PICK-CARRYING','switch','Channel carries traffic: server kept','Канал везёт трафик: сервер не меняется','The program never changes the server of the channel that carries the traffic right now (or when it cannot confirm which one does).','Программа никогда не меняет сервер канала, который сейчас везёт трафик (или когда не удаётся подтвердить, какой именно).','Nothing to do.','Ничего делать не нужно.'],
 ['SERVER-PICK-REQUESTED','switch','Server change handed to Auto','Смена сервера передана Auto','The server check found a faster live server for a channel that is down and carries no traffic. Only Auto changes servers: for the idle reserve while the traffic is on the primary, or for the failed primary while the traffic is on the reserve after an automatic switch.','Проверка серверов нашла более быстрый живой сервер для канала, который не работает и не везёт трафик. Сервер меняет только Auto: у незанятого резерва, пока трафик на основном канале, или у упавшего основного, пока трафик на резерве после автоматического переключения.','Nothing to do.','Ничего делать не нужно.'],
 ['SERVER-PICK-DEFERRED','switch','Server change waits for Auto','Смена сервера ждёт Auto','Auto is not ready to change this server now: a switch or a return is in progress, the reserve is held, a manual switch or hold is set, another change is pending, or the channel is chosen by its server rather than by its tunnel. The request stays valid for 15 minutes.','Auto сейчас не готов менять этот сервер: идёт переключение или возврат, резерв удерживается, включено ручное переключение или удержание, ещё не закончена другая смена или канал выбран по серверу, а не по туннелю. Заявка действует 15 минут.','Nothing to do. If it repeats, choose both channels by their tunnels on the Auto page.','Ничего делать не нужно. Если повторяется, выберите оба канала по туннелю на странице Auto.'],
 ['SERVER-CHANGING','switch','Auto is changing an idle channel server','Auto меняет сервер незанятого канала','Auto put a new server into a channel without traffic (the reserve, or the failed primary while the traffic is on the reserve) and waits (at most 60 s) for it to connect and pass the channel check. Meanwhile it makes no switch decision; the working channel carries the traffic as before.','Auto поставил новый сервер в канал без трафика (резервный или упавший основной, пока трафик на резерве) и ждёт (не дольше 60 с), пока он подключится и пройдёт проверку канала. В это время решений о переключении нет; работающий канал везёт трафик как прежде.','Nothing to do.','Ничего делать не нужно.'],
 ['SERVER-PICK-OFF','switch','Server pick is off','Подбор сервера выключен','The switch "Pick the best server" is off or Auto is off, so no server is changed. The server list is still shown.','Выключатель «Подбирать лучший сервер» выключен или выключен Auto, поэтому сервер не меняется. Список серверов всё равно показан.','Switch on "Pick the best server" in Settings → Channels: primary and reserve (Console: Servers tab) if you want it.','Если нужно, включите «Подбирать лучший сервер» в «Настройки → Каналы: основной и резерв» (в «Пульте» — вкладка «Серверы»).'],
 /* Trust on first use of the VPN servers' keys (server_pin.lua/.py, option server_key_pin warn|enforce|off, default warn). */
 ['SERVER-KEY-PINNED','monitor','Server key remembered','Ключ сервера запомнен','The first healthy check of this server (profile plus its configured host name, never the IP address) remembered its key: the WireGuard peer public key, or the SHA-256 of the OpenVPN CA certificate. From now on the monitor compares the key at most every 10 minutes and whenever the server address changes. A provider pool that gives the profile another server (NordVPN) is a new server and is simply remembered too.','Первая удачная проверка этого сервера (профиль плюс его настроенное имя хоста, но не IP-адрес) запомнила его ключ: публичный ключ пира WireGuard или SHA-256 сертификата CA OpenVPN. Дальше монитор сверяет ключ не чаще раза в 10 минут и при каждой смене адреса сервера. Если пул провайдера даёт профилю другой сервер (NordVPN), это новый сервер, он тоже просто запоминается.','Nothing to do.','Ничего делать не нужно.'],
 ['SERVER-KEY-CHANGED','monitor','Server key changed','Ключ сервера изменился','The same server (profile and host name) now presents another key than the one remembered at first use. A provider can rotate keys, but a changed key is also what a substituted or intercepted server looks like. With server_key_pin enforce Auto does not start when the channel that will carry the traffic has this key (a key only on the other channel does not stop the start) and refuses a move onto this channel until the change is accepted, while leaving the channel stays allowed; with warn (default) it only warns. GL keeps the tunnel itself as configured.','Тот же сервер (профиль и имя хоста) показывает другой ключ, чем запомненный при первом использовании. Провайдер может сменить ключи, но так же выглядит и подменённый или перехваченный сервер. При server_key_pin enforce Auto не запускается, если этот ключ у канала, который понесёт трафик (ключ только у другого канала запуск не останавливает), и отказывается переходить на этот канал, пока смену не примут, а уйти с него можно всегда; при warn (по умолчанию) только предупреждает. Сам туннель GL остаётся как настроен.','Compare the new key (homensai-vpn-server-key list) with the provider (server list or a freshly downloaded config). If it is right: homensai-vpn-server-key accept <profile>. If not: switch the profile off and contact the provider.','Сверьте новый ключ (homensai-vpn-server-key list) с провайдером (список серверов или заново скачанный конфиг). Если верный: homensai-vpn-server-key accept <профиль>. Если нет: выключите профиль и свяжитесь с провайдером.'],
 ['SERVER-KEY-ACCEPTED','monitor','New server key accepted','Новый ключ сервера принят','The administrator accepted the key now presented by a server whose key had changed (homensai-vpn-server-key accept). It is the remembered key from now on and the channel can be used by Auto again.','Администратор принял ключ, который теперь показывает сервер со сменившимся ключом (homensai-vpn-server-key accept). Теперь запомнен он, и Auto снова может использовать канал.','Nothing to do.','Ничего делать не нужно.'],
 ['SERVER-KEY-FORGOTTEN','monitor','Remembered server key removed','Запомненный ключ сервера удалён','The administrator removed the remembered keys of a profile (homensai-vpn-server-key forget). Its next healthy check remembers the key again as a first use, without comparing it with the old one.','Администратор удалил запомненные ключи профиля (homensai-vpn-server-key forget). Следующая удачная проверка снова запомнит ключ как первое использование, без сравнения со старым.','Use forget only after the profile was replaced on purpose (new provider, new config).','Используйте forget только после намеренной замены профиля (новый провайдер, новый конфиг).'],
 ["SERVER-KEY-UNACCEPTED","switch","Changed server key not accepted","Сменившийся ключ сервера не принят","Option server_key_pin is enforce and a channel of the Auto pair has a server whose key changed and was not accepted yet. Auto does not start when the channel that will carry the traffic has such a key. With the key only on the other channel Auto starts and stays off that channel: a failover, a return or a manual switch onto it is refused. Leaving that channel stays allowed, and a Stop or a rollback never depend on keys.","Включена опция server_key_pin enforce, а у канала пары Auto есть сервер со сменившимся и ещё не принятым ключом. Auto не запускается, если такой ключ у канала, который понесёт трафик. Если ключ только у другого канала, Auto запускается и на этот канал не переходит: уход, возврат или ручное переключение на него отклоняются. Уйти с такого канала можно всегда, а Stop и откат от ключей не зависят.","Compare this exact server key with the provider through a known contact or source. Accept it only after confirming that the change is expected. If you cannot verify the key, leave this channel unused. Do not weaken key checking merely to remove the warning; Stop and rollback do not require accepting the key.","Сверьте именно этот ключ сервера с данными провайдера по известному вам каналу связи. Принимайте его только после подтверждения, что замена ожидаема. Если проверить ключ нельзя, оставьте этот канал неиспользуемым. Не ослабляйте проверку ключей ради исчезновения предупреждения; Stop и откат не требуют принятия ключа."],
 ['SERVER-KEY-STATE-CORRUPT','monitor','Remembered server keys unreadable','Запомненные ключи серверов не читаются','The file of remembered server keys (server-keys.json) was damaged. A copy was kept in /var/run/homensai-vpn/server-keys.corrupt.json and remembering starts afresh: every server is a first use again, so a key change made meanwhile cannot be noticed for those servers.','Файл запомненных ключей серверов (server-keys.json) повреждён. Копия сохранена в /var/run/homensai-vpn/server-keys.corrupt.json, запоминание начинается заново: каждый сервер снова первое использование, поэтому смену ключа за это время у них не заметить.','If it repeats, check the flash storage (Diagnostics) and report the copy.','Если повторяется, проверьте флеш-память (Диагностика) и пришлите копию.'],
 ['SERVER-KEY-PROFILE-INVALID','monitor','Server key request not understood','Запрос по ключу сервера не понят','The request to accept a server key named no valid profile (wireguard:<section> or openvpn:<section>) or no key. Nothing was changed.','В запросе на принятие ключа сервера нет верного профиля (wireguard:<секция> или openvpn:<секция>) или ключа. Ничего не изменено.','Reload the page and press the button again.','Обновите страницу и нажмите кнопку снова.'],
 ['SERVER-KEY-NOT-CHANGED','monitor','No such key change to accept','Такой смены ключа нет','The page asked to accept a server key, but the router no longer has this unaccepted change with exactly this key: it was accepted already, the profile was forgotten, or the server shows yet another key now. Nothing was accepted.','Страница попросила принять ключ сервера, но на роутере уже нет этой непринятой смены именно с этим ключом: её уже приняли, профиль забыт или сервер теперь показывает ещё один ключ. Ничего не принято.','Wait for the next status update, check the key now shown with the provider and accept it again if it is right.','Дождитесь обновления состояния, сверьте показанный теперь ключ с провайдером и, если он верный, примите его снова.'],
 /* WireGuard kernel events of GL's patched WireGuard (wg_events.py/.lua, option wg_events): sensor evidence, never a failure proof alone. */
 ['KEYPAIR-CREATED','monitor','WireGuard handshake completed','Рукопожатие WireGuard выполнено','The tunnel answered a handshake (new session keys). The WAN diagnosis takes it as evidence that the tunnel and the internet work.','Туннель ответил на рукопожатие (новые ключи сессии). Диагностика WAN считает это признаком того, что туннель и интернет работают.','Nothing to do.','Ничего делать не нужно.'],
 ['REKEY-TIMEOUT','monitor','WireGuard handshake not answered','Рукопожатие WireGuard без ответа','The server did not answer a key renewal in time. One lost packet causes it too, so it only makes the monitor check this channel more often; it never switches by itself.','Сервер не ответил вовремя на обновление ключей. Так бывает и от одного потерянного пакета, поэтому монитор лишь чаще проверяет этот канал; само по себе это не переключает.','Nothing to do unless the channel checks fail too.','Ничего делать не нужно, если проверки канала проходят.'],
 ['REKEY-GIVEUP','monitor','WireGuard stopped retrying the handshake','WireGuard перестал повторять рукопожатие','WireGuard gave up the key renewal after repeated timeouts. The monitor checks this channel densely; Auto still decides only by its own checks.','WireGuard прекратил обновление ключей после повторных таймаутов. Монитор часто проверяет этот канал; Auto по-прежнему решает только по своим проверкам.','If it repeats, check the server and the WAN of the router.','Если повторяется, проверьте сервер и WAN роутера.'],
 /* Network advisor and master slider (advisor.py/advisor_control.py, lua/advisor.lua, 2.1.0-alpha9): why a slider position or own values were not applied. */
 ['ADVISOR-BUSY-OUTAGE','setup','Not now: an outage is in progress','Не сейчас: идёт обрыв','The slider settings are never changed while a channel outage is still open in the network journal, so the running decision keeps its rules.','Настройки ползунка не меняются, пока в журнале сети открыт обрыв канала: текущее решение доводится по своим правилам.','Try again when the channels are healthy.','Повторите, когда каналы снова здоровы.'],
 ['ADVISOR-BUSY-SWITCH','setup','Not now: a switch is in progress','Не сейчас: идёт переключение','The slider settings are never changed while Auto is switching or returning (or the route is down), so a switch never runs with half-changed rules.','Настройки ползунка не меняются, пока Auto переключает или возвращает канал (или маршрут недоступен): переключение никогда не идёт с наполовину изменёнными правилами.','Try again in a minute.','Повторите через минуту.'],
 ['ADVISOR-CALM-UNKNOWN','setup','Calm state not confirmed','Спокойствие не подтверждено','The router could not read fresh evidence that no outage or switch is in progress, and no evidence of calm counts as no calm. Nothing was changed.','Роутер не смог прочитать свежие данные о том, что обрыва и переключения нет, а нет подтверждения — значит, нет и спокойствия. Ничего не изменено.','Check that monitoring runs (System), then try again.','Проверьте, что мониторинг работает («Система»), и повторите.'],
 ['ADVISOR-MODEL-CONSECUTIVE','setup','Slider does not apply to this detector','Ползунок не действует на этот детектор','The failure detector is the previous rule "failures in a row". The slider and the advisor tune the HMM detector only, so nothing is changed.','Детектор сбоя — прежнее правило «ошибки подряд». Ползунок и советчик настраивают только детектор HMM, поэтому ничего не меняется.','Choose the standard or fast HMM detector (Expert: failure detector) if you want to use the slider.','Если нужен ползунок, выберите стандартный или быстрый детектор HMM («Эксперт: детектор сбоя»).'],
 ['ADVISOR-NO-RECOMMENDATION','setup','No recommendation to apply','Нет рекомендации для применения','There is no fresh recommendation to move the slider: too few events in the window, the current position is already the best, or the nightly calculation has not run yet.','Свежей рекомендации сдвинуть ползунок нет: мало событий за окно, текущее положение уже лучшее или ночной расчёт ещё не выполнялся.','Nothing to do; or move the slider yourself.','Ничего делать не нужно; или сдвиньте ползунок сами.'],
 ['ADVISOR-OUT-OF-BOUNDS','setup','Value outside the safe range','Значение вне безопасного диапазона','A value is outside its safe range (threshold θ and P(G) 0.50–0.99, short-outage length 1–15 s, primary stability 30–600 s, return after a failed reserve 0–60 s). Nothing was changed.','Значение вне безопасного диапазона (порог θ и P(G) 0,50–0,99, длина «короткого обрыва» 1–15 с, стабильность основного 30–600 с, возврат после отказа резерва 0–60 с). Ничего не изменено.','Choose a value inside the range.','Выберите значение внутри диапазона.'],
 ['ADVISOR-PG-BELOW-THETA','setup','Return threshold below leave threshold','Порог возврата ниже порога ухода','P(G), the confidence needed to return to the primary, must not be lower than θ, the confidence needed to leave it; otherwise Auto could return to a channel it would leave again at once.','P(G) — уверенность, нужная для возврата на основной, — не может быть ниже θ, уверенности для ухода с него; иначе Auto мог бы вернуться на канал, с которого тут же снова ушёл бы.','Raise P(G) to at least θ.','Поднимите P(G) не ниже θ.'],
 ['ADVISOR-RESCUE-ABOVE-STABLE','setup','Rescue return longer than primary stability','Возврат после отказа резерва дольше стабильности','The return after a failed reserve must not wait longer than the normal primary stability.','Возврат после отказа резерва не может ждать дольше обычной стабильности основного.','Lower the rescue time or raise the primary stability (Settings → How fast to switch).','Уменьшите время возврата после отказа резерва или увеличьте стабильность основного («Настройки → Как быстро переключать»).'],
 ['ADVISOR-RIDE-NOT-BELOW-LEAVE','setup','This setting would never leave a dead channel','Такая настройка не уйдёт с мёртвого канала','With these detector values the outage the model rides out is not shorter than the time it needs to leave, so a dead primary might never be left. The router refuses such a setting.','С такими значениями детектора обрыв, который модель пережидает, не короче времени, нужного для ухода, и с мёртвого основного канала можно не уйти никогда. Роутер такую настройку не принимает.','Lower θ or the short-outage length.','Уменьшите θ или длину «короткого обрыва».'],
 ['ADVISOR-RANGE','setup','Slider value not accepted','Значение ползунка не принято','The position or a value sent by the page is not a number in its range, or the mode/window is unknown. Nothing was changed.','Положение или значение со страницы — не число в своём диапазоне, или режим/окно неизвестны. Ничего не изменено.','Reload the page and try again.','Обновите страницу и повторите.'],
 ['ADVISOR-ONCE-A-DAY','setup','Auto-adaptation already moved today','Автоподстройка сегодня уже двигала','In mode Auto the slider moves by at most one step (0.1) a day, so a single bad day cannot swing the settings.','В режиме «Авто» ползунок сдвигается не больше чем на один шаг (0,1) в сутки, чтобы один плохой день не раскачал настройки.','Nothing to do.','Ничего делать не нужно.'],
 ['ADVISOR-UNAVAILABLE','setup','Auto-adaptation status unavailable','Состояние автоподстройки недоступно','The monitor could not build the advisor status in this pass (no curve file, an unreadable journal or an internal error). Switching itself is not affected.','Монитор не смог собрать состояние советчика в этом проходе (нет файла кривой, журнал не читается или внутренняя ошибка). На само переключение это не влияет.','If it stays, reinstall the package.','Если не проходит — переустановите пакет.'],
 ['AUTO-RESUME-PENDING','service','Auto is coming back after a restart','Auto возвращается после перезапуска','The router was restarted with Auto on. Auto finishes an interrupted switch, waits for the VPN channels and turns itself back on.','Роутер перезапускался с включённым Auto. Auto завершает прерванное переключение, ждёт VPN-каналы и включается сам.','Nothing needs to be pressed; it usually takes 3–4 minutes after power-on. If Auto is still off after 10 minutes, turn it on with the Auto switch.','Нажимать ничего не нужно; обычно это 3–4 минуты после включения питания. Если через 10 минут Auto всё ещё выключен, включите его переключателем Auto.'],
 /* Interruption codes (01.11.2026, interruption.lua): why the service started; one event per start. */
 ["RESTART-CLEAN", "service", "Clean restart", "Штатный перезапуск", "The router or the service was stopped properly (reboot, service stop or restart, settings reload, package update). This is not an interruption.", "Роутер или служба остановлены штатно (перезагрузка, остановка или перезапуск службы, применение настроек, обновление пакета). Это не прерывание.", "Nothing to do. Auto that the owner switched on comes back by itself.", "Делать ничего не нужно. Auto, включённый владельцем, вернётся сам."],
 ["RESTART-FIRST-START", "service", "First start", "Первый запуск", "The program has no record of how its previous run ended: the first start after installing or updating the package. This is not an interruption.", "У программы нет записи о том, как закончилась прошлая работа: первый запуск после установки или обновления пакета. Это не прерывание.", "Nothing to do. From the next start the cause is recorded exactly.", "Делать ничего не нужно. Со следующего запуска причина записывается точно."],
 ["RESTART-PROCESS", "service", "Process restarted", "Процесс перезапущен", "The Auto supervisor or the monitor ended without a service stop (crash or kill) and the system restarted it. The router itself did not reboot; the recovery puts an unfinished switch right.", "Супервизор Auto или мониторинг завершились без остановки службы (сбой или принудительное завершение), и система перезапустила процесс. Сам роутер не перезагружался; восстановление доводит незавершённое переключение.", "Once is harmless. If it repeats (the log says restart limit), save the system log (logread | grep homensai) and send it to the maintainer.", "Один раз — не страшно. Если повторяется (в журнале restart limit), сохраните системный журнал (logread | grep homensai) и передайте разработчику."],
 ["RESTART-INTERRUPTED-BOOT", "service", "Cut while starting", "Сбой при запуске", "Power was lost or the router hung while it was starting: the previous start never finished its recovery.", "Питание пропало или роутер завис во время запуска: прошлый запуск не завершил восстановление.", "Check the power supply and cable. If it repeats after every power-on, leave the router on for 10 minutes and check Events and reasons on Home (Console: Log tab) for a code after this one.", "Проверьте блок питания и кабель. Если повторяется после каждого включения, оставьте роутер включённым на 10 минут и посмотрите в «Событиях и причинах» на «Главной» (в «Пульте» — вкладка «Журнал») код после этого."],
 ["RESTART-INTERRUPTED-SWITCH", "service", "Cut during a switch", "Сбой при переключении", "Power was lost (or the router hung) while Auto was switching the channel. After the start the switch is rolled back to the saved channel order.", "Питание пропало (или роутер завис), когда Auto переключал канал. После запуска переключение откатывается к сохранённому порядку каналов.", "Wait 3–4 minutes. If ROLLBACK-GIVEN-UP or PAIR-RECOVERY-REQUIRED follows, open that code. Check the power supply.", "Подождите 3–4 минуты. Если затем появится ROLLBACK-GIVEN-UP или PAIR-RECOVERY-REQUIRED, откройте этот код. Проверьте питание."],
 ["RESTART-INTERRUPTED-RESERVE-HOLD", "service", "Cut on the reserve", "Сбой на резерве", "Power was lost (or the router hung) while the reserve channel was in use. After the start the reserve is kept or the router returns to the main channel by its rules.", "Питание пропало (или роутер завис), когда работал резервный канал. После запуска резерв сохраняется или роутер возвращается на основной канал по своим правилам.", "Nothing needs to be pressed. Check the power supply if it repeats.", "Нажимать ничего не нужно. Если повторяется, проверьте питание."],
 ["RESTART-INTERRUPTED-OPERATION", "service", "Cut in normal operation", "Сбой при обычной работе", "Power was lost (or the router hung) while Auto was on and working on the main channel, with no switch in progress.", "Питание пропало (или роутер завис), когда Auto был включён и работал на основном канале, без переключения.", "Nothing needs to be pressed: Auto comes back by itself (AUTO-RESUME-PENDING). Check the power supply if it repeats.", "Нажимать ничего не нужно: Auto вернётся сам (AUTO-RESUME-PENDING). Если повторяется, проверьте питание."],
 ["RESTART-INTERRUPTED-AUTO-OFF", "service", "Cut with Auto off", "Сбой при выключенном Auto", "Power was lost (or the router hung) while Auto was off. Nothing was switching; Auto stays off.", "Питание пропало (или роутер завис), когда Auto был выключен. Переключений не было; Auto остаётся выключенным.", "Nothing to do. Check the power supply if it repeats.", "Делать ничего не нужно. Если повторяется, проверьте питание."],
 ["RESTART-PLANNED-REBOOT", "service", "Planned reboot", "Плановая перезагрузка", "The router was rebooted by its own timer (GL: System → Scheduled reboot, gl_timer). The service stopped properly; this is neither an interruption nor a power cut.", "Роутер перезагружен собственным таймером (GL: Система → Перезагрузка по расписанию, gl_timer). Служба остановлена штатно; это не прерывание и не отключение питания.", "Nothing to do. Auto that the owner switched on comes back by itself.", "Делать ничего не нужно. Auto, включённый владельцем, вернётся сам."],
 ["RESTART-KERNEL-CRASH", "service", "Router kernel crash", "Сбой ядра роутера", "The previous run ended with a crash of the router's kernel: a new record appeared in the GL crash log (pstore / mtdoops, /tmp/log/crash_log). Not a power cut. The recovery puts an unfinished switch right as after any interruption.", "Прошлая работа закончилась сбоем ядра роутера: в журнале сбоев GL появилась новая запись (pstore / mtdoops, /tmp/log/crash_log). Это не отключение питания. Восстановление доводит незавершённое переключение, как после любого прерывания.", "Once is rare but possible. If it repeats, save /tmp/log/crash_log (or run homensai-vpn-diag) and send it to the maintainer.", "Один раз — редко, но бывает. Если повторяется, сохраните /tmp/log/crash_log (или выполните homensai-vpn-diag) и пришлите разработчику."],
 ['STATUS-STALE','service','Status is old','Статус устарел','The monitor is switched on but its data is older than 90 seconds.','Мониторинг включён, но его данные старше 90 секунд.','Wait a minute and reload the page; if the lamp is red press “Restore monitoring” in Monitoring service (Settings → System and diagnostics; Console: System tab). If it stays, see Help → “The page is old, empty or says the monitor is not running”.','Подождите минуту и обновите страницу; если лампа красная, нажмите «Восстановить мониторинг» в «Службе мониторинга» (Настройки → Система и диагностика; в «Пульте» — вкладка «Система»). Если не помогло, см. «Помощь» → «Страница старая, пустая или пишет, что мониторинг не работает».'],
 ['RPC-PLUGIN','service','Program plugin missing','Нет модуля программы','The plugin that connects the page to the program is missing on the router.','На роутере нет модуля, который связывает страницу с программой.','Reinstall the package (opkg install) and sign out of LuCI and in again.','Переустановите пакет (opkg install) и выйдите из LuCI и войдите снова.'],
 ['RPC-INPUT-SIZE','service','Request too large','Слишком большой запрос','The request was rejected because it was too large or too complex.','Запрос отклонён: он слишком большой или сложный.','Reload the page and repeat. This normally does not happen with the standard page.','Обновите страницу и повторите. С обычной страницей этого не бывает.'],
 ['CLIENT-CABLE-LINK-DOWN','helper','Cable adapter is down','Кабельный адаптер не подключён','The cable adapter you chose is not up.','Выбранный кабельный адаптер не поднят.','Plug the cable into a LAN port of the router and run the helper again with the right adapter number (Get-NetAdapter).','Вставьте кабель в LAN-порт роутера и запустите помощника снова с правильным номером адаптера (Get-NetAdapter).'],
 ["CLIENT-CABLE-ADDRESS-AMBIGUOUS", "helper", "Cable IPv4 address is ambiguous", "Неоднозначный IPv4-адрес кабеля", "The selected cable has no single preferred IPv4 address.", "На выбранном кабеле нет единственного предпочтительного IPv4-адреса.", "Inspect the real LAN subnet and adapter addresses read-only; the factory 192.168.8.x example is not universal.", "Проверьте реальную LAN-подсеть и адреса адаптера только чтением; заводской пример 192.168.8.x не универсален."],
 ["CLIENT-CABLE-NOT-LOCAL", "helper", "Selected cable does not reach this router locally", "Выбранный кабель не ведёт к роутеру локально", "The explicit cable route to the management address is not a direct local path.", "Явно выбранный кабельный маршрут к адресу управления не является прямым локальным путём.", "Verify the correct router, cable and subnet. Do not automatically disable Wi-Fi or alter computer routes.", "Проверьте нужный роутер, кабель и подсеть. Не отключайте Wi-Fi и не меняйте маршруты компьютера автоматически."],
 ["CLIENT-CABLE-PROBE-ROUTE-MISMATCH", "helper", "Cable probe route differs", "Маршрут кабельной проверки не совпадает", "The chosen interface cannot route the probe destinations through the expected router.", "Выбранный интерфейс не направляет проверочные запросы через ожидаемый роутер.", "Inspect interface/gateway ownership. The current helper creates no temporary routes; do not delete unrelated routes to bypass this refusal.", "Изучите интерфейс и владельца шлюза. Текущий помощник не создаёт временных маршрутов; не удаляйте посторонние маршруты ради обхода отказа."],
 ["CLIENT-CABLE-HTTPS-FAILED", "helper", "Bound HTTPS check failed", "Привязанная HTTPS-проверка не прошла", "The source-bound HTTPS requests through the selected cable did not succeed.", "HTTPS-запросы с привязкой к выбранному кабелю не завершились успешно.", "Inspect router health, actual route and competing client software. Any host-network correction is a separate deliberate action, not an automatic helper repair.", "Проверьте роутер, фактический маршрут и программы клиента. Исправление сети компьютера — отдельное осознанное действие, а не автоматический ремонт помощником."],
 ["CLIENT-GATEWAY-MISMATCH", "helper", "Client path uses another gateway", "Клиентский путь использует другой шлюз", "The observed default client path is not through the named router.", "Наблюдаемый обычный путь клиента не проходит через указанный роутер.", "Verify the intended network and interface, or choose an explicit cable witness. Do not silently stop another VPN or change its routes.", "Проверьте нужную сеть и интерфейс либо выберите явную кабельную проверку. Не останавливайте другой VPN и не меняйте его маршруты незаметно."],
 ['CLIENT-DNS-CONFIG-UNVERIFIED','helper','DNS settings unverified','Настройки DNS не подтверждены','The computer uses a DNS server other than the router.','Компьютер использует DNS-сервер, отличный от роутера.','Set the DNS of the computer to automatic (from the router) for the test.','Установите DNS на компьютере автоматически (от роутера) на время теста.'],
 ["CLIENT-IPV6-DEFAULT-UNVERIFIED", "helper", "IPv6 route unverified", "Маршрут IPv6 не подтверждён", "The computer has an IPv6 default route that the helper cannot verify.", "У компьютера есть маршрут IPv6 по умолчанию, который помощник не может проверить.", "This witness has not excluded another IPv6 path. Preserve its current settings and choose a supported explicit IPv4 witness or a separately authorized correction; the helper does not disable IPv6.", "Эта проверка не исключила другой IPv6-путь. Сохраните текущие настройки и выберите поддерживаемую явную IPv4-проверку либо отдельно разрешённую коррекцию; помощник не отключает IPv6."],
 ["CLIENT-PROBE-ROUTE-CONFLICT", "helper", "Legacy probe-route conflict", "Конфликт проверочных маршрутов старой версии", "This code belongs to an older route-adding helper; the current helper is route-free.", "Код относится к старому помощнику, добавлявшему маршруты; текущий маршруты не создаёт.", "Read the current route owners and preserve evidence. Remove an old owned route only as a separately verified cleanup; never delete arbitrary routes.", "Изучите владельцев маршрутов и сохраните данные. Удаляйте старый собственный маршрут лишь после отдельной проверки; не удаляйте произвольные маршруты."],
 ['CLIENT-CANCELLED','helper','Cancelled','Отменено','You did not type TEST, so the trial did not start.','Вы не ввели TEST, поэтому тест не начался.','Run again and type TEST only when you are ready for a short interruption.','Запустите снова и вводите TEST, только когда готовы к короткому разрыву.'],
 ['CLIENT-TRIAL-UNCONFIRMED','helper','Trial not confirmed','Тест не подтверждён','The router did not get a valid confirmation from the computer in time.','Роутер не получил вовремя верное подтверждение от компьютера.','The router returned to the previous route. Check the cable and run again.','Роутер вернулся на прежний маршрут. Проверьте кабель и запустите снова.'],
 ['CLIENT-RESERVE-NOT-VERIFIED','helper','Reserve not verified','Резерв не подтверждён','The computer did not see the reserve VPN exit.','Компьютер не увидел выход через резервный VPN.','Check that the reserve VPN really works (the Reserve card on Home; Console: Channels tab) and try again.','Проверьте, что резервный VPN действительно работает (карточка «Резерв» на «Главной»; в «Пульте» — вкладка «Каналы»), и повторите.'],
 ['POWERSHELL-7-REQUIRED','helper','PowerShell 7 needed','Нужен PowerShell 7','The helper needs PowerShell 7 (pwsh).','Помощнику нужен PowerShell 7 (pwsh).','Install it: winget install Microsoft.PowerShell, then start the helper with pwsh.','Установите: winget install Microsoft.PowerShell, затем запускайте помощника через pwsh.'],
 ['PRIVATE-LAN-ROUTER-REQUIRED','helper','Router address is not private','Адрес роутера не частный','The helper accepts only a private LAN address.','Помощник принимает только частный адрес локальной сети.','Use the router address such as http://192.168.8.1:8080/.','Укажите адрес роутера вида http://192.168.8.1:8080/.'],
 ['TELEGRAM-TOKEN-REQUIRED','telegram','Bot token missing','Нет токена бота','No bot token is stored.','Токен бота не сохранён.','Enter the token in Settings → Telegram notifications (Console: System tab) (see Help → “Telegram reports do not arrive”).','Введите токен в «Настройки → Уведомления в Telegram» (в «Пульте» — вкладка «Система») (см. «Помощь» → «Отчёты в Telegram не приходят»).'],
 ['TELEGRAM-TOKEN-FORMAT','telegram','Token looks wrong','Токен выглядит неверно','The token does not have the form 123456789:AAH… .','Токен не похож на 123456789:AAH….','Copy the whole token from @BotFather again, without spaces.','Скопируйте токен из @BotFather заново целиком, без пробелов.'],
 ['TELEGRAM-TOKEN-REJECTED','telegram','Token rejected by Telegram','Telegram отклонил токен','Telegram says the token is not valid.','Telegram сообщает, что токен недействителен.','Create a new token in @BotFather (/token) and enter it again.','Создайте новый токен в @BotFather (/token) и введите заново.'],
 ['TELEGRAM-DESTINATION-FORMAT','telegram','Chat ID looks wrong','ID чата выглядит неверно','The chat ID has a wrong form.','У ID чата неверный вид.','Use digits (123456789, or -100… for a group) or @channel_name.','Используйте цифры (123456789 или -100… для группы) или @имя_канала.'],
 ['TELEGRAM-PERMISSION','telegram','Bot cannot write there','Бот не может туда писать','The bot has no right to write to this chat.','У бота нет права писать в этот чат.','Press Start in the bot chat, or make the bot an administrator of the group/channel.','Нажмите Start в чате с ботом или сделайте бота администратором группы/канала.'],
 ['TELEGRAM-RATE-LIMIT','telegram','Too many messages','Слишком много сообщений','Telegram asks to wait before the next message.','Telegram просит подождать перед следующим сообщением.','Wait; the program retries by itself. Use a longer report interval.','Подождите; программа повторит сама. Поставьте более длинный интервал отчётов.'],
 ['TELEGRAM-DNS','telegram','Telegram address not found','Адрес Telegram не найден','The router cannot resolve the Telegram address.','Роутер не может найти адрес Telegram.','Check the internet and DNS on the router.','Проверьте интернет и DNS на роутере.'],
 ['TELEGRAM-TLS','telegram','Secure connection failed','Защищённое соединение не удалось','The secure connection to Telegram failed.','Защищённое соединение с Telegram не удалось.','Check the router date and time and the ca-bundle package.','Проверьте дату и время на роутере и пакет ca-bundle.'],
 ['TELEGRAM-DELIVERY-UNKNOWN','telegram','Delivery not confirmed','Доставка не подтверждена','A report was sent but Telegram did not confirm it.','Отчёт отправлен, но Telegram не подтвердил доставку.','Check the chat. The program does not send a duplicate automatically.','Проверьте чат. Программа не отправляет дубликат автоматически.'],
 ['TELEGRAM-DELIVERED','telegram','Delivered','Доставлено','A report was delivered.','Отчёт доставлен.','Nothing to do.','Делать ничего не нужно.'],
 ['TELEGRAM-TEST-DELIVERED','telegram','Test delivered','Тест доставлен','The test message was delivered.','Тестовое сообщение доставлено.','Nothing to do.','Делать ничего не нужно.'],
 ['TELEGRAM-CONFIG','telegram','Telegram setup incomplete','Настройка Telegram неполная','The Telegram settings are incomplete or invalid.','Настройки Telegram неполные или неверные.','Open Settings → Telegram notifications (Console: System tab) and fill in the token and the chat ID again.','Откройте «Настройки → Уведомления в Telegram» (в «Пульте» — вкладка «Система») и заполните токен и ID чата заново.'],
 ['TELEGRAM-CLOCK-BACKWARD','telegram','Clock went back','Часы пошли назад','The router clock went back, so reports are paused.','Часы роутера пошли назад, поэтому отчёты приостановлены.','Check the router date and time (NTP).','Проверьте дату и время роутера (NTP).'],
 ['TELEGRAM-STATE-CORRUPT','telegram','Report state damaged','Состояние отчётов повреждено','The saved report state is damaged.','Сохранённое состояние отчётов повреждено.','The program recovers it by itself; save the Telegram settings again if it stays.','Программа восстанавливает его сама; если не прошло, сохраните настройки Telegram заново.'],
 ['SETUP-INVALID','setup','Invalid input','Неверный ввод','A wizard field has an invalid value.','В поле мастера неверное значение.','Correct the highlighted fields and review again.','Исправьте выделенные поля и проверьте ещё раз.'],
 ['SETUP-RANGE','setup','Value out of range','Значение вне диапазона','A number is outside the allowed range.','Число вне допустимого диапазона.','Use a value inside the range shown next to the field.','Укажите значение в диапазоне, показанном рядом с полем.'],
 ['SETUP-SAVE-FAILED','setup','Settings not saved','Настройки не сохранены','The router did not confirm the saved settings.','Роутер не подтвердил сохранение настроек.','Try again. Check free space and the log (logread) if it repeats.','Повторите. Если снова, проверьте свободное место и журнал (logread).'],
 ["SETUP-STOP-FIRST","setup","Stop Auto first","Сначала остановите Auto","The change is not allowed while Auto is running.","Изменение недопустимо, пока работает Auto.","Stop Auto with its normal control and wait for confirmation. Check the current channel and whether the app permits this setting to be changed. A retained reserve may keep some settings unavailable. Do not edit routing rules by hand to bypass the block; complete the offered recovery when the required channel is available.","Остановите Auto штатным переключателем и дождитесь подтверждения. Проверьте текущий канал и разрешает ли программа менять эту настройку. При сохранённом резерве часть настроек может оставаться недоступной. Не меняйте правила маршрутизации вручную ради снятия блокировки; завершите предложенное восстановление, когда нужный канал доступен."],
 ['SETUP-SAVE-UNCONFIRMED','setup','Save not confirmed','Сохранение не подтверждено','The router did not answer the save in time. The change may or may not have been written.','Роутер не ответил на сохранение вовремя. Изменение могло записаться, а могло и нет.','Reload the page and look at the setting. If it is wrong, save again. If the router reports unsaved changes, see Help.','Обновите страницу и посмотрите настройку. Если она неверная, сохраните ещё раз. Если роутер сообщает о несохранённых изменениях, см. «Помощь».'],
 ['SETUP-PENDING-DELTA','setup','Unsaved router changes','Есть несохранённые изменения роутера','The router has uncommitted changes of this program’s settings.','На роутере есть неприменённые изменения настроек этой программы.','Open LuCI → Unsaved changes and apply or revert them, then repeat.','Откройте LuCI → «Несохранённые изменения», примените или отмените их и повторите.'],
 ['SETUP-PRIMARY-RESERVE-DISABLED','setup','Primary or reserve is off','Основной или резервный отключён','The chosen primary or reserve profile is not enabled for monitoring.','Выбранный основной или резервный профиль не включён для наблюдения.','Choose both channels again in Settings → Channels: primary and reserve (Console: Channels → Change the channel pair).','Выберите оба канала заново в «Настройки → Каналы: основной и резерв» (в «Пульте» — «Каналы» → «Изменить пару каналов»).'],
 ['SETUP-PROFILES','setup','Profiles not found','Профили не найдены','A selected profile no longer exists on the router.','Выбранного профиля больше нет на роутере.','Choose existing profiles again in Settings → Channels: primary and reserve (Console: Channels → Change the channel pair).','Выберите существующие профили заново в «Настройки → Каналы: основной и резерв» (в «Пульте» — «Каналы» → «Изменить пару каналов»).'],
 ['SPEED-DISABLED','speed','Speed tests are off','Тесты скорости выключены','Speed tests are switched off.','Тесты скорости выключены.','Turn them on in Settings → Speed test: parameters → “Allow speed tests” (Console: Servers → Speed test parameters).','Включите их в «Настройки» → «Тест скорости: параметры» → «Разрешить тесты скорости» (в «Пульте» — «Серверы» → «Параметры теста скорости»).'],
 ['SPEED-DAILY-LIMIT','speed','Daily quota used','Суточная квота исчерпана','The daily data quota for tests is used up.','Суточная квота данных для тестов исчерпана.','Wait for tomorrow or raise the quota in the speed test settings.','Дождитесь завтра или увеличьте квоту в настройках тестов скорости.'],
 ['SPEED-COOLDOWN','speed','Please wait','Нужна пауза','A test of this server ran recently.','Этот сервер тестировали недавно.','Try again later.','Повторите позже.'],
 ['SPEED-BUSY','speed','Another test is running','Уже идёт другой тест','Another test is running.','Уже выполняется другой тест.','Wait until it finishes or cancel it.','Дождитесь его окончания или отмените.'],
 ['SPEED-TRAFFIC-BUSY','speed','VPN is busy','VPN сейчас занят','The VPN carries more traffic than the limit, so the test was skipped.','Через VPN идёт трафика больше лимита, поэтому тест пропущен.','Run the test when the VPN is less busy or raise the limit.','Запустите тест, когда VPN менее загружен, или поднимите лимит.'],
 ['SPEED-ROUTE-UNVERIFIED','speed','Test route unverified','Путь теста не подтверждён','It is not proven that the test goes through the chosen VPN.','Не доказано, что тест идёт через выбранный VPN.','Make sure the VPN is connected and try again.','Убедитесь, что VPN подключён, и повторите.'],
 ['SPEED-PROFILE-INACTIVE','speed','VPN not connected','VPN не подключён','The VPN to test is not connected.','VPN для теста не подключён.','Connect the profile in GL.iNet first; this program never connects VPNs.','Сначала подключите профиль в GL.iNet; эта программа VPN не подключает.'],
 ['SPEED-NETWORK','speed','Test network error','Сетевая ошибка теста','The test could not connect.','Тесту не удалось соединиться.','Check the VPN and the internet and try again.','Проверьте VPN и интернет и повторите.'],
 ['SPEED-CANCELLED','speed','Cancelled','Отменено','The test was cancelled.','Тест отменён.','Nothing to do.','Делать ничего не нужно.'],
 ['SCAN-DEADLINE-EXCEEDED','speed','Check took too long','Проверка заняла слишком много времени','The “Check now” request did not finish in time.','Запрос «Проверить сейчас» не завершился вовремя.','Press the button again after a minute. Check that the monitor is running.','Нажмите кнопку ещё раз через минуту. Проверьте, что мониторинг работает.'],
 ['SCAN-STATE-CORRUPT','speed','Check state damaged','Состояние проверки повреждено','The saved state of the check is damaged.','Сохранённое состояние проверки повреждено.','Press “Check now” again; it creates a new state.','Нажмите «Проверить сейчас» ещё раз; создастся новое состояние.'],
 ['CLOCK-001','data','Wrong router date','Неверная дата на роутере','The router date is impossible or jumped.','Дата роутера невозможна или скачет.','Set the time zone and enable NTP in LuCI → System → System. Statistics wait for a correct clock.','Задайте часовой пояс и включите NTP в LuCI → «Система» → «Система». Статистика ждёт верных часов.'],
 ["HISTORY-001", "data", "History unavailable", "История недоступна", "The saved controller history cannot be read.", "Сохранённую историю контроллера не удаётся прочитать.", "Preserve primary/backup history and inspect checksums, clock, permissions and storage. Do not delete it or promise an automatic fresh history; corrupt recovery evidence can block switching.", "Сохраните основной/резервный журнал и проверьте checksum, время, права и хранилище. Не удаляйте его и не обещайте автоматическое создание новой истории; повреждённые данные восстановления могут блокировать переходы."],
 ['FAULT-CERTIFIED-AUTO-REQUIRED','switch','Transition test needs running Auto','Для теста перехода нужен работающий Auto','The test needs fresh confirmation of the current channel and a healthy alternative. Prepared continuous pair Auto uses its own private state; the legacy bounded mode still needs its LAN certificate.','Тесту нужны свежие подтверждения текущего канала и исправного второго. Подготовленный непрерывный Auto использует собственное закрытое состояние; прежнему ограниченному режиму по-прежнему нужен LAN-сертификат.','Check both VPN channels and turn Auto on with the Auto switch (Home; Console: top strip). Reopen the transition test after fresh observations arrive.','Проверьте оба VPN и включите Auto переключателем (на «Главной»; в «Пульте» — вверху). Вернитесь к тесту перехода после свежих наблюдений.'],
 ['FAULT-UNVERIFIED','switch','Failure test not confirmed','Сбой не подтверждён','The router did not confirm that the simulated failure was applied or removed.','Роутер не подтвердил, что имитация сбоя применена или снята.','Press “Stop and remove fault” in Failure test (Home → Tests; Console: Auto tab), check on Home that traffic works, then try again.','Нажмите «Остановить и снять сбой» в «Тесте сбоя» (Главная → «Проверки»; в «Пульте» — вкладка «Auto»), проверьте на «Главной», что трафик идёт, и повторите.'],
 ['FAULT-UNKNOWN','switch','Failure test result unknown','Итог теста сбоя неизвестен','The result of the failure request is unknown.','Итог запроса на сбой неизвестен.','Reload the page. If the VPN has no traffic, press “Stop and remove fault”.','Обновите страницу. Если через VPN нет трафика, нажмите «Остановить и снять сбой».'],
 ['FAULT-CANCEL-UNKNOWN','switch','Cancel not confirmed','Отмена не подтверждена','The cancel request was sent but not confirmed.','Запрос на отмену отправлен, но не подтверждён.','Check Failure test (Home → Tests; Console: Auto tab) after a minute. The failure also ends by itself when its time is over (a timeout in the router).','Проверьте «Тест сбоя» (Главная → «Проверки»; в «Пульте» — вкладка «Auto») через минуту. Сбой также заканчивается сам по истечении времени (таймаут в роутере).'],
 ['FAULT-RPC-UNCONFIRMED','switch','No answer from the router','Нет ответа от роутера','The page did not get a confirmed answer to the failure request.','Страница не получила подтверждённого ответа на запрос сбоя.','Reload the page and look at the state of the test before repeating.','Обновите страницу и посмотрите состояние теста, прежде чем повторять.'],
 ['FAULT-FIELDS','switch','Invalid request','Неверный запрос','The failure request had wrong fields.','В запросе сбоя неверные поля.','Reload the page (Ctrl+F5) and try again.','Обновите страницу (Ctrl+F5) и повторите.'],
 ["FAULT-HISTORY-UNAVAILABLE", "data", "Failure history unavailable", "История сбоев недоступна", "The saved history of failure tests cannot be read.", "Сохранённую историю тестов сбоя не удаётся прочитать.", "Keep the stored fault-history files and inspect read/write/integrity errors. Cleanup and test outcome must be checked separately; a new history is not guaranteed automatically.", "Сохраните файлы истории тестов и проверьте чтение/запись/целостность. Очистка и итог теста проверяются отдельно; новая история сама по себе не гарантируется."],
 ['FAULT-STATE-CORRUPT','switch','Failure state damaged','Состояние сбоя повреждено','The saved state of a failure test is damaged.','Сохранённое состояние теста сбоя повреждено.','Press “Stop and remove fault”; the program cleans up its own traffic rule.','Нажмите «Остановить и снять сбой»; программа уберёт собственное правило трафика.'],
 ['FAULT-NFT-QUERY-FAILED','switch','Cannot read the firewall rule','Не удаётся прочитать правило межсетевого экрана','The router did not answer a query about the program’s own temporary rule.','Роутер не ответил на запрос о собственном временном правиле программы.','Wait for the timeout of the test (up to 3 minutes) and try again; nothing else is changed.','Дождитесь таймаута теста (до 3 минут) и повторите; больше ничего не меняется.'],
 ['FAULT-TABLE-ALREADY-EXISTS','switch','A previous test is still active','Предыдущий тест ещё активен','The program’s own temporary rule from a previous test still exists.','Собственное временное правило программы от прошлого теста ещё существует.','Press “Stop and remove fault” or wait for its timeout.','Нажмите «Остановить и снять сбой» или дождитесь таймаута.'],
 ['HISTORY-PARTIAL','data','History partly aggregated','История частично объединена','Older measurements were aggregated or pruned to keep the storage and the answer size small.','Старые измерения объединены или удалены, чтобы хранилище и ответ роутера оставались небольшими.','Nothing to fix. Recent days are complete; very old details are summarised.','Исправлять нечего. Недавние дни полные; очень старые подробности сведены в итоги.'],
 ['SPEED-HISTORY-TRUNCATED','speed','Speed history shortened','История скорости сокращена','Only the newest speed results are kept; older ones were dropped.','Хранятся только новейшие результаты скорости; старые удалены.','Nothing to fix. Export what you need before it is dropped.','Исправлять нечего. Сохраните нужное до удаления.'],
 ['JOURNAL-INTEGRITY-FAILED','switch','Journal failed its check','Журнал не прошёл проверку','The transaction journal has a wrong checksum.','У журнала транзакций неверная контрольная сумма.','Do not delete it. Follow router-test-kit/EMERGENCY.md and ask for help with the output of show.','Не удаляйте его. Следуйте router-test-kit/EMERGENCY.md и просите помощи, приложив вывод show.'],
 // Self-check and self-restore of the installed program files (TODO item 15, homensai-vpn-integrity)
 ['INTEGRITY-MODE-DIFFERS','service','File permissions differ','Права файлов отличаются','Every program file has the right content, but some file permissions differ from the package list. The service starts as usual.','Содержимое всех файлов программы верное, но у части файлов права отличаются от списка пакета. Служба запускается как обычно.','Nothing urgent; a reinstall of the package sets the permissions again.','Ничего срочного; переустановка пакета вернёт права.'],
 ['INTEGRITY-OK','service','Program files verified','Файлы программы проверены','At the service start every installed program file matched the checksum list shipped in the package.','При запуске службы каждый установленный файл программы совпал со списком контрольных сумм из пакета.','Nothing to do.','Ничего делать не нужно.'],
 ['INTEGRITY-RESTORED','service','Damaged program files restored','Повреждённые файлы программы восстановлены','At the service start some program files did not match their checksums. They were replaced from the verified pristine copy kept on the router, checked again, and the service started normally. Settings, terms, journal and history were not touched.','При запуске службы часть файлов программы не совпала с контрольными суммами. Они заменены из проверенной эталонной копии на роутере, проверены снова, служба запущена как обычно. Настройки, условия, журнал и история не затронуты.','Nothing urgent. If it repeats, the flash memory may be wearing out: save a backup and reinstall the package.','Ничего срочного. Если повторяется, возможно, изнашивается флеш-память: сохраните резервную копию и переустановите пакет.'],
 ['INTEGRITY-FILE-RESTORED','service','A program file was restored','Файл программы восстановлен','One damaged, missing or wrongly permitted program file was put back from the pristine copy (system log line).','Один повреждённый, отсутствующий или с неверными правами файл программы возвращён из эталонной копии (строка системного журнала).','Nothing to do.','Ничего делать не нужно.'],
 ['INTEGRITY-FILE-DAMAGED','service','A program file is damaged','Файл программы повреждён','An installed program file does not match the checksum shipped in the package.','Установленный файл программы не совпадает с контрольной суммой из пакета.','The service restores it by itself when it can. Otherwise reinstall the same package version.','Служба восстанавливает его сама, когда может. Иначе переустановите ту же версию пакета.'],
 ['INTEGRITY-FILE-MISSING','service','A program file is missing','Файл программы отсутствует','An installed program file listed in the package is missing.','Установленный файл программы из списка пакета отсутствует.','The service restores it by itself when it can. Otherwise reinstall the same package version.','Служба восстанавливает его сама, когда может. Иначе переустановите ту же версию пакета.'],
 ['INTEGRITY-FILE-MODE','service','A program file has wrong permissions','У файла программы неверные права','An installed program file has other permissions than in the package (for example a start script that is no longer executable).','У установленного файла программы права отличаются от пакета (например, скрипт запуска больше не исполняемый).','The service restores the permissions by itself when it can. Otherwise reinstall the same package version.','Служба восстанавливает права сама, когда может. Иначе переустановите ту же версию пакета.'],
 ['INTEGRITY-MANIFEST-UNREADABLE','service','Checksum list damaged','Список контрольных сумм повреждён','The list of checksums shipped in the package is missing or damaged, so the files cannot be compared with it.','Список контрольных сумм из пакета отсутствует или повреждён, поэтому сверить файлы с ним нельзя.','The service takes the list from the pristine copy when it can. Otherwise reinstall the same package version.','Служба берёт список из эталонной копии, когда может. Иначе переустановите ту же версию пакета.'],
 ['INTEGRITY-SOURCE-MISSING','service','No pristine copy to restore from','Нет эталонной копии для восстановления','Damaged program files were found, but the pristine copy of the package files is not on the router (for example the installation ended before the copy was made).','Найдены повреждённые файлы программы, но эталонной копии файлов пакета на роутере нет (например, установка прервалась до её создания).','Reinstall the same package version; the installation makes the copy again.','Переустановите ту же версию пакета; установка снова создаст копию.'],
 ['INTEGRITY-SOURCE-DAMAGED','service','Pristine copy damaged','Эталонная копия повреждена','The pristine copy failed its own checksum, so nothing was restored from it.','Эталонная копия не прошла собственную проверку контрольной суммы, поэтому из неё ничего не восстановлено.','Reinstall the same package version; the installation replaces the copy.','Переустановите ту же версию пакета; установка заменит копию.'],
 ['INTEGRITY-SOURCE-VERSION','service','Pristine copy is another version','Эталонная копия другой версии','The pristine copy belongs to another package version than the installed files (for example after an interrupted update), so nothing was restored from it.','Эталонная копия относится к другой версии пакета, чем установленные файлы (например, после прерванного обновления), поэтому из неё ничего не восстановлено.','Install the package version you want again and let the installation finish.','Установите нужную версию пакета ещё раз и дождитесь окончания установки.'],
 ['INTEGRITY-RESTORE-LIMIT','service','Restore limit reached','Достигнут предел восстановлений','The program restores its files at most once per router start and three times in 24 hours, so a damage that keeps coming back cannot cause a loop.','Программа восстанавливает свои файлы не чаще раза за запуск роутера и трёх раз за сутки, чтобы постоянно возвращающееся повреждение не вызвало цикл.','The damage keeps coming back: check free flash space, save a backup and reinstall the package.','Повреждение возвращается: проверьте свободное место на флеше, сохраните резервную копию и переустановите пакет.'],
 ['INTEGRITY-RESTORE-FAILED','service','Restore did not succeed','Восстановление не удалось','Files were copied from the pristine copy but did not pass the check afterwards (for example the flash is full or read-only).','Файлы скопированы из эталонной копии, но после этого не прошли проверку (например, флеш заполнен или только для чтения).','Check free space and the system log, then reinstall the package.','Проверьте свободное место и системный журнал, затем переустановите пакет.'],
 ['INTEGRITY-NEVER-RESTORED','service','Owner data is never restored','Данные владельца не восстанавливаются','A restore never writes your settings, terms acceptance, journal, history or certificates.','Восстановление никогда не записывает ваши настройки, принятие условий, журнал, историю и сертификаты.','Nothing to do.','Ничего делать не нужно.'],
 ['INTEGRITY-LUA-DAMAGED','service','Lua files damaged, Python runs','Файлы Lua повреждены, работает Python','Damaged Lua program files could not be restored, so the monitor and the Auto supervisor run on the proven Python code. Auto keeps its own checks.','Повреждённые файлы программы на Lua восстановить не удалось, поэтому мониторинг и Auto работают на проверенном коде Python. Auto сохраняет свои проверки.','Reinstall the same package version to return to Lua.','Переустановите ту же версию пакета, чтобы вернуться на Lua.'],
 ['INTEGRITY-C-MODULE-DAMAGED','service','C module damaged, pure Lua runs','C-модуль повреждён, работает чистый Lua','The fast C module canon_c.so is damaged and could not be restored; JSON is processed by the slower pure Lua code.','Быстрый C-модуль canon_c.so повреждён и не восстановлен; JSON обрабатывает более медленный код на чистом Lua.','Reinstall the same package version.','Переустановите ту же версию пакета.'],
 ['INTEGRITY-SERVICE-STOPPED','service','Program damaged, service stays off','Программа повреждена, служба не запущена','Both the Lua and the Python program files are damaged and could not be restored. The service stays off; an existing VPN-only protection stays in place and LAN traffic is not changed.','Повреждены и не восстановлены файлы программы и на Lua, и на Python. Служба не запущена; существующая защита «только VPN» остаётся, трафик LAN не меняется.','Reinstall the same package version. If LAN clients have no internet, use homensai-vpn-emergency (see EMERGENCY.md).','Переустановите ту же версию пакета. Если у клиентов LAN нет интернета, используйте homensai-vpn-emergency (см. EMERGENCY.md).'],
 ['INTEGRITY-UNVERIFIED','service','Files not verified','Файлы не проверены','There is neither a checksum list nor a pristine copy (a hand-copied or older installation), so the files were not checked. The service starts as before.','Нет ни списка контрольных сумм, ни эталонной копии (установка вручную или старая), поэтому файлы не проверены. Служба запускается как раньше.','Install the package with opkg to enable the self-check.','Установите пакет через opkg, чтобы включить самопроверку.'],
 ['INTEGRITY-DEFERRED','service','Check postponed during installation','Проверка отложена на время установки','A package installation was running, so the files were not checked yet. The check runs again by itself as soon as the installation ends (it waits up to 10 minutes).','Шла установка пакета, поэтому файлы ещё не проверялись. Проверка запустится сама, как только установка закончится (ожидание до 10 минут).','Nothing to do; the result replaces this line within a few minutes.','Ничего делать не нужно; через несколько минут здесь появится результат проверки.'],
 ['INTEGRITY-RECHECKED','service','Postponed check done','Отложенная проверка выполнена','The self-check postponed during the installation ran after the installation ended; the code after it is the result (for example INTEGRITY-OK).','Самопроверка, отложенная на время установки, выполнена после её окончания; код после неё — результат (например, INTEGRITY-OK).','Nothing to do unless the result shows a problem.','Ничего делать не нужно, если результат не показывает проблему.'],
 ['INTEGRITY-RECHECK-DAMAGED','service','Damaged files found after installation','После установки найдены повреждённые файлы','The postponed self-check found damaged or missing program files after the installation. A running service is restarted once so the self-check restores them from the pristine copy; Auto is not started by this. A stopped service is not started; its next start restores the files.','Отложенная самопроверка после установки нашла повреждённые или отсутствующие файлы программы. Работающая служба один раз перезапускается, чтобы самопроверка восстановила их из эталонной копии; Auto при этом не запускается. Остановленная служба не запускается; файлы восстановит её следующий запуск.','Check the result line after the restart; if files stay damaged, reinstall the same package version.','Проверьте строку результата после перезапуска; если файлы остались повреждёнными, переустановите ту же версию пакета.'],
 ['INTEGRITY-RECHECK-TIMEOUT','service','Postponed check timed out','Отложенная проверка не дождалась установки','A package operation still held the opkg lock 10 minutes after the service started, so the postponed self-check did not run. The service keeps running as before.','Через 10 минут после запуска службы операция с пакетами всё ещё держала блокировку opkg, поэтому отложенная самопроверка не выполнилась. Служба работает как раньше.','When no package operation runs any more, restart the service (/etc/init.d/homensai-vpn restart) or reboot the router; if /var/lock/opkg.lock stays without a running opkg, reboot.','Когда операций с пакетами больше нет, перезапустите службу (/etc/init.d/homensai-vpn restart) или перезагрузите роутер; если /var/lock/opkg.lock остаётся без работающего opkg — перезагрузите роутер.'],
 ['INTEGRITY-SNAPSHOT-MADE','service','Pristine copy saved','Эталонная копия сохранена','The installation verified the unpacked files and saved them as the pristine copy for later self-restore (about 1.5 MB).','Установка проверила распакованные файлы и сохранила их как эталонную копию для самовосстановления (около 1,5 МБ).','Nothing to do.','Ничего делать не нужно.'],
 ['INTEGRITY-SNAPSHOT-REFUSED','service','Pristine copy not saved','Эталонная копия не сохранена','The installation did not save the pristine copy because the unpacked files did not match their checksums or the copy could not be written.','Установка не сохранила эталонную копию: распакованные файлы не совпали с контрольными суммами или копию не удалось записать.','Reinstall the package; check the system log.','Переустановите пакет; проверьте системный журнал.'],
 ['INTEGRITY-PAYLOAD-DAMAGED','service','Installed files damaged, service not started','Установленные файлы повреждены, служба не запущена','During the installation the freshly unpacked program files did not match the checksum list of the package (a file damaged or missing, or the list itself damaged). No pristine copy was saved. When the previous working version is kept, it is restored and started automatically (UPGRADE-ROLLED-BACK); otherwise the service stays off.','При установке только что распакованные файлы программы не совпали со списком контрольных сумм пакета (файл повреждён или отсутствует либо повреждён сам список). Эталонная копия не сохранена. Если сохранена предыдущая рабочая версия, она автоматически восстанавливается и запускается (UPGRADE-ROLLED-BACK); иначе служба остаётся выключенной.','Download the package again, check its checksum and install it again; check the free space on the router.','Скачайте пакет заново, сверьте его контрольную сумму и установите ещё раз; проверьте свободное место на роутере.'],
 ['INTEGRITY-HELPER-FAILED','service','File check tool failed, service not started','Сбой инструмента проверки файлов, служба не запущена','During the installation the file check tool itself ended with an unexpected result (missing, not executable or crashed), so the installation is not verified. When the previous working version is kept, it is restored and started automatically (UPGRADE-ROLLED-BACK); otherwise the service stays off.','При установке сам инструмент проверки файлов завершился неожиданно (отсутствует, не запускается или упал), поэтому установка не подтверждена. Если сохранена предыдущая рабочая версия, она автоматически восстанавливается и запускается (UPGRADE-ROLLED-BACK); иначе служба остаётся выключенной.','Install the same package again; if it repeats, keep the installation output and ask the maintainer.','Установите тот же пакет ещё раз; если повторяется, сохраните вывод установки и обратитесь к разработчику.'],
 ['UPGRADE-ROLLED-BACK','service','Update damaged, previous version restored','Обновление повреждено, восстановлена прежняя версия','The new package failed its file check during the installation (damaged files or an unverified check tool). The previous working version was restored from its verified pristine copy and started; your settings, journal and history were not touched. Auto runs again only if you had started it before. The new version is not installed.','Новый пакет не прошёл проверку файлов при установке (повреждённые файлы или неподтверждённый инструмент проверки). Прежняя рабочая версия восстановлена из проверенной эталонной копии и запущена; ваши настройки, журнал и история не тронуты. Auto снова работает, только если вы запускали его раньше. Новая версия не установлена.','Download the new package again, check its checksum and install it again; this line disappears after a successful installation.','Скачайте новый пакет заново, сверьте контрольную сумму и установите ещё раз; эта строка исчезнет после успешной установки.'],
 ['UPGRADE-ROLLBACK-UNAVAILABLE','service','Update damaged, no previous version to restore','Обновление повреждено, прежней версии для восстановления нет','The new package failed its file check during the installation, and no verified copy of exactly the version that was running before was kept on the router (none, damaged or an older one), so nothing was restored and the service stays off.','Новый пакет не прошёл проверку файлов при установке, а проверенной копии именно той версии, что работала до обновления, на роутере нет (нет совсем, повреждена или более старая), поэтому ничего не восстановлено и служба остаётся выключенной.','Download the package again, check its checksum and install it again; check the free space on the router.','Скачайте пакет заново, сверьте контрольную сумму и установите ещё раз; проверьте свободное место на роутере.'],
 ['UPGRADE-ROLLBACK-FAILED','service','Update damaged, restoring the previous version failed','Обновление повреждено, восстановить прежнюю версию не удалось','The new package failed its file check, and the previous version copied back from its pristine copy did not pass the check afterwards (for example the flash is full or read-only). The service stays off.','Новый пакет не прошёл проверку файлов, а прежняя версия, скопированная из эталонной копии, после этого тоже не прошла проверку (например, флеш заполнен или только для чтения). Служба остаётся выключенной.','Free flash space, then install a package whose checksum you have verified; if it repeats, keep the installation output and ask the maintainer.','Освободите место на флеше и установите пакет с проверенной контрольной суммой; если повторяется, сохраните вывод установки и обратитесь к разработчику.'],
 ['UPGRADE-ROLLBACK-VERSION','service','Kept copy is another version','Сохранённая копия другой версии','The verified pristine copy holds another version than the one that was running before the update (for example an older one, kept when a later copy could not be saved), so it is not restored: an older program could misread newer settings and records.','Проверенная эталонная копия содержит не ту версию, что работала до обновления (например, более старую, оставшуюся, когда новую копию сохранить не удалось), поэтому она не восстанавливается: старая программа может неверно прочитать более новые настройки и записи.','Install a verified package of the version you want; the service stays off until then.','Установите проверенный пакет нужной версии; до этого служба остаётся выключенной.'],
 ['UPGRADE-NOT-INSTALLED','service','Rolled-back update not installed','Откаченное обновление не установлено','The package manager ran the installation step of an update that was already rolled back. Its files are not on the router (the previous version runs), so the step is refused and the package stays not configured.','Менеджер пакетов снова запустил шаг установки обновления, которое уже было откачено. Его файлов на роутере нет (работает прежняя версия), поэтому шаг отклонён и пакет остаётся ненастроенным.','Install a verified package again with opkg install --force-reinstall; until then the previous version keeps running.','Установите проверенный пакет заново командой opkg install --force-reinstall; до этого работает прежняя версия.'],
 ['MAINTENANCE-IN-PROGRESS','service','Package update in progress','Идёт обновление пакета','A package installation, upgrade or removal is running. Until it ends, Auto starts nothing new and the buttons that could switch a channel or load the line (Start, manual switch, return, failure test, speed test) are refused; Stop always works. The mark ends with the operation, at the latest after 15 minutes or at the next boot.','Идёт установка, обновление или удаление пакета. Пока оно не закончится, Auto ничего нового не запускает, а кнопки, которые могут переключить канал или нагрузить линию (Старт, ручное переключение, возврат, тест отказа, тест скорости), отклоняются; Стоп работает всегда. Отметка снимается вместе с операцией, самое позднее через 15 минут или при следующей загрузке.','Wait until the installation finishes and reload the page.','Дождитесь окончания установки и обновите страницу.'],
 ['MAINTENANCE-INTERRUPTED','service','Package update did not finish','Обновление пакета не завершилось','A package installation, upgrade or removal did not finish (for example a power cut or a stopped installation). Its mark no longer blocks anything. The installed version may be incomplete.','Установка, обновление или удаление пакета не завершилось (например, пропало питание или установку прервали). Его отметка больше ничего не блокирует. Установленная версия может быть неполной.','Install the package again; this line disappears after a successful installation.','Установите пакет ещё раз; эта строка исчезнет после успешной установки.'],
 ['MAINTENANCE-CLEAR-FAILED','service','Interrupted package mark not cleared','Отметка прерванной установки не снята','At the service start a mark left by an interrupted package operation could not be moved into the report (flash full or read-only). It blocks nothing; the page still shows the interrupted operation.','При запуске службы отметку прерванной операции с пакетом не удалось перенести в отчёт (флеш заполнен или только для чтения). Она ничего не блокирует; страница по-прежнему показывает прерванную операцию.','Free flash space and install the package again.','Освободите место на флеше и установите пакет ещё раз.'],
 ['INTEGRITY-SNAPSHOT-NO-SPACE','service','No space for the pristine copy','Нет места для эталонной копии','Less than 8 MB was free on the flash, so the pristine copy was not saved; the self-restore is not available.','На флеше было свободно меньше 8 МБ, поэтому эталонная копия не сохранена; самовосстановление недоступно.','Free flash space and reinstall the package.','Освободите место на флеше и переустановите пакет.'],
 ['INTEGRITY-TOOL-MISSING','service','Self-check tool missing, Auto not started','Нет инструмента самопроверки, Auto не запущен','The self-check tool is not installed, so the program files cannot be verified. The page and the channel monitoring keep working, but Auto is not started until the installation is verified again.','Инструмент самопроверки не установлен, поэтому файлы программы нельзя проверить. Страница и наблюдение за каналами работают, но Auto не запускается, пока установка снова не будет проверена.','Reinstall the package (the same version is enough); Auto comes back by itself if you had started it.','Переустановите пакет (подойдёт та же версия); Auto вернётся сам, если вы его запускали.'],
 ['INTEGRITY-TOOL-DAMAGED','service','Self-check tool damaged','Инструмент самопроверки повреждён','The self-check tool itself does not match its checksum. It is put back from the pristine copy when that copy is intact; otherwise the files cannot be verified, so the page and the channel monitoring keep working but Auto is not started.','Сам инструмент самопроверки не совпадает со своей контрольной суммой. Он восстанавливается из эталонной копии, если она цела; иначе файлы проверить нельзя, поэтому страница и мониторинг каналов работают, но Auto не запускается.','Reinstall the package; Auto can then be started again.','Переустановите пакет; после этого Auto можно снова запустить.'],
 ['INTEGRITY-TOOL-FAILED','service','Self-check gave no answer, Auto not started','Самопроверка не ответила, Auto не запущен','The self-check tool crashed or gave no usable answer at the service start, so the program files are not verified. The page and the channel monitoring keep working, but Auto is not started.','Инструмент самопроверки упал или не дал понятного ответа при запуске службы, поэтому файлы программы не проверены. Страница и мониторинг каналов работают, но Auto не запускается.','Reinstall the package; if it repeats, keep the system log and ask the maintainer.','Переустановите пакет; если повторяется, сохраните системный журнал и обратитесь к разработчику.'],
 ['INTEGRITY-NO-AUTO','service','Installation not verified, Auto not started','Установка не проверена, Auto не запущен','The self-check tool is missing, damaged or gave no answer, so the installation cannot be verified. The page and the channel monitoring keep working, but Auto is not started.','Инструмент самопроверки отсутствует, повреждён или не ответил, поэтому установку проверить нельзя. Страница и мониторинг каналов работают, но Auto не запускается.','Reinstall the package; Auto can then be started again.','Переустановите пакет; после этого Auto можно снова запустить.'],
 ['INTEGRITY-AUTO-BLOCKED','service','Start refused: the file self-check forbids Auto','Старт отклонён: самопроверка файлов запрещает Auto','The self-check at the service start found the installation unverified or damaged, so no Auto supervisor runs. Start is refused instead of being queued for later.','Самопроверка при запуске службы нашла установку непроверенной или повреждённой, поэтому Auto не работает. Старт отклоняется, а не ставится в очередь на потом.','Reinstall the package (the same version is enough), then press Start again.','Переустановите пакет (подойдёт та же версия), затем снова нажмите Старт.'],
 ['SERVICE-AUTO-OFF','service','Start refused: the Auto service is switched off','Старт отклонён: служба Auto выключена','Monitoring runs (it always starts), but the service option enabled is not 1 (left by an older version that stopped the monitor, changed by hand, or the config could not be read), so no Auto supervisor was started. Start is refused instead of being queued for later.','Мониторинг работает (он запускается всегда), но параметр службы enabled не равен 1 (его оставила старая версия, остановившая мониторинг, его изменили вручную, или конфиг не прочитался), поэтому Auto не запущен. Старт отклоняется, а не ставится в очередь на потом.','Press “Switch the Auto service on” in the Monitoring block (Overview or Settings → System and diagnostics), or over SSH: uci set homensai_vpn.main.enabled=1; uci commit homensai_vpn. This starts no Auto by itself; then press Start again.','Нажмите «Включить службу Auto» в блоке «Мониторинг» (Обзор или Настройки → Система и диагностика) или по SSH: uci set homensai_vpn.main.enabled=1; uci commit homensai_vpn. Само по себе это Auto не запускает; затем снова нажмите Старт.'],
];
